import unittest

from alpha.greeting import greeting


class GreetingTest(unittest.TestCase):
    def test_default(self):
        self.assertEqual(greeting(), "hello, demo")

    def test_none(self):
        self.assertEqual(greeting(None), "hello, demo")

    def test_name(self):
        self.assertEqual(greeting("ann"), "hello, ann")

    def test_limit_64_code_points_ok(self):
        self.assertEqual(greeting("a" * 64), "hello, " + "a" * 64)

    def test_over_limit_raises(self):
        with self.assertRaises(ValueError) as cm:
            greeting("a" * 65)
        self.assertIn("64", str(cm.exception))

    def test_counts_code_points_not_bytes(self):
        # 64 two-byte code points are within the limit
        self.assertEqual(greeting("é" * 64), "hello, " + "é" * 64)
        with self.assertRaises(ValueError):
            greeting("é" * 65)


if __name__ == "__main__":
    unittest.main()
